def stat(d):
    p = np.asarray(d['pre'], dtype=float)
    if p.shape[1] < 2:
        return 0.0
    a = p[:, 0::2].mean(axis=1)
    b = p[:, 1::2].mean(axis=1)
    if a.std() == 0 or b.std() == 0:
        return 0.0
    r = np.corrcoef(a, b)[0, 1]
    return float(r) if np.isfinite(r) else 0.0

def stat(d):
    imp = np.asarray(d['post'], dtype=float) - np.asarray(d['pre'], dtype=float)
    g = np.asarray(d['young'], dtype=bool)
    if g.sum() < 2 or (~g).sum() < 2:
        return 0.0
    s1 = imp[g].std(ddof=1)
    s2 = imp[~g].std(ddof=1)
    if s1 <= 0 or s2 <= 0:
        return 0.0
    return float(abs(np.log(s1 / s2)))
